<?php
/**
 * The editing screen (Appearance > Customize).
 *
 * The controls are not written out one by one. They are generated by walking
 * the same defaults tree the templates read from, so every editable string on
 * the page is guaranteed to have a field - the two can never drift apart.
 *
 * Collections the owner adds to and removes from - trades, videos, FAQ
 * entries, glossary terms - are ordinary posts instead, so they get the full
 * WordPress editor. Those are skipped here.
 */
defined('ABSPATH') || exit;

/** Groups handled as posts, not Customizer fields. */
function tsa_customizer_skip() {
	return array('trades', 'videos.items', 'faq.items', 'glossary.items', 'site.domain', 'videos.layout', 'hero.layout');
}

/** Section order and human titles. */
function tsa_customizer_sections() {
	// In the order the sections appear on the page, so the list reads like a
	// walk down the site.
	return array(
		'site'          => __('Site basics', 'tradeskillapps'),
		'nav'           => __('Menu links', 'tradeskillapps'),
		'navCta'        => __('Menu button', 'tradeskillapps'),
		'hero'          => __('Hero', 'tradeskillapps'),
		'multiplayer'   => __('Learn together (how it works)', 'tradeskillapps'),
		'knowledge'     => __('Build expert trade knowledge', 'tradeskillapps'),
		'tradesSection' => __('Explore the trades', 'tradeskillapps'),
		'licensing'     => __('Annual licensing', 'tradeskillapps'),
		'partners'      => __('For partners', 'tradeskillapps'),
		'footer'        => __('Footer', 'tradeskillapps'),
	);
}

/** 'headlineEm' -> 'Headline - highlighted part' */
function tsa_label($key, $path = '') {
	$overrides = array(
		'headline'     => __('Headline', 'tradeskillapps'),
		'headlineEm'   => __('Headline - highlighted part', 'tradeskillapps'),
		'quoteEm'      => __('Quote - highlighted part', 'tradeskillapps'),
		'eyebrow'      => __('Small label above the headline', 'tradeskillapps'),
		'lede'         => __('Intro paragraph', 'tradeskillapps'),
		'body'         => __('Body text', 'tradeskillapps'),
		'note'         => __('Note', 'tradeskillapps'),
		'alt'          => __('Description for screen readers', 'tradeskillapps'),
		'src'          => __('Picture', 'tradeskillapps'),
		'href'         => __('Links to', 'tradeskillapps'),
		'label'        => __('Button label', 'tradeskillapps'),
		'srcSet'       => __('Responsive set (leave blank if you replace the picture)', 'tradeskillapps'),
		'n'            => __('Number', 'tradeskillapps'),
		'eye'          => __('Small label', 'tradeskillapps'),
		'q'            => __('Question', 'tradeskillapps'),
		'a'            => __('Answer', 'tradeskillapps'),
		'points'       => __('Bullet points (one per line)', 'tradeskillapps'),
		'skills'       => __('Skills (one per line)', 'tradeskillapps'),
		'caption'      => __('Caption lines (one per line)', 'tradeskillapps'),
		'chain'        => __('Words in the chain (one per line)', 'tradeskillapps'),
		'strip'        => __('Strip under the buttons (one per line)', 'tradeskillapps'),
	);
	if (isset($overrides[$key])) return $overrides[$key];
	if (ctype_digit((string) $key)) return sprintf(__('Item %d', 'tradeskillapps'), ((int) $key) + 1);
	$s = preg_replace('/([a-z])([A-Z])/', '$1 $2', (string) $key);
	return ucfirst(strtolower($s));
}

/** Long strings get a textarea, short ones a single line. */
function tsa_control_type($value) {
	if (!is_string($value)) return 'text';
	return (strlen($value) > 70 || strpos($value, '. ') !== false) ? 'textarea' : 'text';
}

function tsa_customize_register($wp_customize) {
	$wp_customize->add_panel('tsa_content', array(
		'title'       => __('XVR Trade Skills content', 'tradeskillapps'),
		'description' => __('Every word and picture on the page. Trades, videos, FAQ entries and glossary terms are edited as posts in the main menu instead, because you add and remove those. Note: clearing a text field leaves that spot empty on the page - it does not bring the original wording back. The original is shown underneath each field.', 'tradeskillapps'),
		'priority'    => 20,
	));

	$defaults = tsa_defaults();
	$skip     = tsa_customizer_skip();

	foreach (tsa_customizer_sections() as $group => $title) {
		if (!isset($defaults[$group])) continue;

		$section = 'tsa_' . strtolower($group);

		$wp_customize->add_section($section, array(
			'title' => $title,
			'panel' => 'tsa_content',
		));

		$priority = 10;
		tsa_walk_node($wp_customize, $defaults[$group], $group, $section, $skip, $priority);

		// Choices, not sentences, so they get proper dropdowns instead of the
		// text boxes the generic walk would produce.
		if ($group === 'hero') {
			$wp_customize->add_setting(tsa_key('hero.layout'), array(
				'default'           => tsa_default('hero.layout'),
				'sanitize_callback' => 'tsa_sanitize_hero_layout',
				'transport'         => 'refresh',
			));
			$wp_customize->add_control(tsa_key('hero.layout'), array(
				'label'       => __('Layout', 'tradeskillapps'),
				'description' => __('How the opening screen is built.', 'tradeskillapps'),
				'section'     => $section, 'type' => 'select', 'priority' => $priority++,
				'choices'     => array(
					'split'   => __('Words left, photograph right, on a dark band', 'tradeskillapps'),
					'overlay' => __('One full-width photograph with the words over it', 'tradeskillapps'),
				),
			));
		}

		if ($group === 'videos') {
			$wp_customize->add_setting(tsa_key('videos.layout'), array(
				'default'           => tsa_default('videos.layout'),
				'sanitize_callback' => 'tsa_sanitize_video_layout',
				'transport'         => 'refresh',
			));
			$wp_customize->add_control(tsa_key('videos.layout'), array(
				'label'       => __('Layout', 'tradeskillapps'),
				'description' => __('How the films are arranged.', 'tradeskillapps'),
				'section'     => $section, 'type' => 'select', 'priority' => $priority++,
				'choices'     => array(
					'feature' => __('First film large, the rest beneath', 'tradeskillapps'),
					'grid'    => __('All the same size', 'tradeskillapps'),
				),
			));
		}

		// Where enquiries are delivered. Not part of the page text, so it is
		// added by hand rather than generated.
		if ($group === 'contact') {
			$wp_customize->add_setting('tsa_contact_to', array(
				'default' => '', 'sanitize_callback' => 'sanitize_email', 'transport' => 'refresh',
			));
			$wp_customize->add_control('tsa_contact_to', array(
				'label'       => __('Send enquiries to', 'tradeskillapps'),
				'description' => __('Leave blank to use the site administrator address.', 'tradeskillapps'),
				'section'     => 'tsa_contact', 'type' => 'email', 'priority' => $priority++,
			));
		}
	}
}
add_action('customize_register', 'tsa_customize_register');

/** Recursively turn a defaults node into Customizer controls. */
function tsa_walk_node($wp_customize, $node, $path, $section, $skip, &$priority) {
	if (in_array($path, $skip, true)) return;

	// an image: picture + alt text
	if (is_array($node) && isset($node['src']) && array_key_exists('alt', $node)) {
		$wp_customize->add_setting(tsa_key($path . '.src'), array(
			'default' => '', 'sanitize_callback' => 'tsa_sanitize_media', 'transport' => 'refresh',
		));
		$wp_customize->add_control(new WP_Customize_Media_Control($wp_customize, tsa_key($path . '.src'), array(
			'label' => tsa_label('src'), 'section' => $section, 'mime_type' => 'image',
			'priority' => $priority++,
			'description' => tsa_path_hint($path),
		)));
		$wp_customize->add_setting(tsa_key($path . '.alt'), array(
			'default' => $node['alt'], 'sanitize_callback' => 'sanitize_text_field', 'transport' => 'refresh',
		));
		$wp_customize->add_control(tsa_key($path . '.alt'), array(
			'label' => tsa_label('alt'), 'section' => $section, 'type' => 'text', 'priority' => $priority++,
		));
		foreach ($node as $k => $v) {
			if (in_array($k, array('src', 'alt'), true)) continue;
			tsa_walk_node($wp_customize, $v, $path . '.' . $k, $section, $skip, $priority);
		}
		return;
	}

	// a plain list of short strings -> one per line
	if (is_array($node) && $node && array_keys($node) === range(0, count($node) - 1)
		&& count(array_filter($node, 'is_string')) === count($node)) {
		$leaf = substr($path, strrpos($path, '.') === false ? 0 : strrpos($path, '.') + 1);
		$wp_customize->add_setting(tsa_key($path), array(
			'default' => implode("\n", $node), 'sanitize_callback' => 'sanitize_textarea_field', 'transport' => 'refresh',
		));
		$wp_customize->add_control(tsa_key($path), array(
			'label'       => tsa_label($leaf),
			'description' => __('One per line. Add or remove lines to change how many appear.', 'tradeskillapps'),
			'section'     => $section, 'type' => 'textarea', 'priority' => $priority++,
		));
		return;
	}

	if (is_array($node)) {
		foreach ($node as $k => $v) {
			tsa_walk_node($wp_customize, $v, $path . '.' . $k, $section, $skip, $priority);
		}
		return;
	}

	// a single string
	$leaf  = substr($path, strrpos($path, '.') === false ? 0 : strrpos($path, '.') + 1);
	$type  = tsa_control_type($node);
	$crumb = tsa_path_hint($path);

	$wp_customize->add_setting(tsa_key($path), array(
		'default'           => $node,
		'sanitize_callback' => $type === 'textarea' ? 'sanitize_textarea_field' : 'sanitize_text_field',
		'transport'         => 'refresh',
	));
	$desc = $crumb;
	if (is_string($node) && $node !== '' && mb_strlen($node) <= 160) {
		/* translators: %s is the text the site shipped with */
		$orig = sprintf(__('Original: %s', 'tradeskillapps'), $node);
		$desc = $desc === '' ? $orig : $desc . ' - ' . $orig;
	}
	$wp_customize->add_control(tsa_key($path), array(
		'label'       => tsa_label($leaf),
		'description' => $desc,
		'section'     => $section,
		'type'        => $type,
		'priority'    => $priority++,
	));
}

/** "Stages > Item 2" - so repeated blocks are tellable apart in a long list. */
function tsa_path_hint($path) {
	$parts = explode('.', $path);
	array_shift($parts);          // the group is already the section title
	array_pop($parts);            // the field is already the label
	if (!$parts) return '';
	$out = array();
	foreach ($parts as $p) $out[] = tsa_label($p);
	return implode(' > ', $out);
}

/** An attachment id, or an empty string when the picture is cleared. */
function tsa_sanitize_media($value) {
	if ($value === '' || $value === null) return '';
	return is_numeric($value) ? (string) absint($value) : esc_url_raw($value);
}

/** Only the two hero layouts the template knows how to draw. */
function tsa_sanitize_hero_layout($value) {
	return in_array($value, array('split', 'overlay'), true) ? $value : 'split';
}

/** Only the two layouts the template knows how to draw. */
function tsa_sanitize_video_layout($value) {
	return in_array($value, array('feature', 'grid'), true) ? $value : 'feature';
}
